package com.bananalab.lite;
import java.util.*;import org.json.*;
/** Own small perceptron ranks verified grammar programs. No external model or arbitrary-code generation. */
final class MethodRanker{
 static final int D=64;static volatile JSONObject model=new JSONObject();
 static float[] features(String q){float[] x=new float[D];for(String word:ChatLanguage.normalize(q).split(" "))x[(word.hashCode()&0x7fffffff)%(D-1)]+=1;float norm=0;for(float v:x)norm+=v*v;if(norm>0){norm=(float)Math.sqrt(norm);for(int i=0;i<D-1;i++)x[i]/=norm;}x[D-1]=1;return x;}
 static float score(JSONObject m,String id,float[] x)throws Exception{JSONArray w=m.optJSONArray(id);float out=0;if(w!=null)for(int i=0;i<D;i++)out+=(float)w.getDouble(i)*x[i];return out;}
 static List<MethodProgram> order(String q,String family)throws Exception{final JSONObject current=model;final float[] x=features(q);List<MethodProgram> list=new ArrayList<>();for(MethodProgram p:MethodProgram.grammar())if(p.family.equals(family))list.add(p);Collections.sort(list,new Comparator<MethodProgram>(){public int compare(MethodProgram a,MethodProgram b){try{return Float.compare(score(current,b.id(),x),score(current,a.id(),x));}catch(Exception e){return 0;}}});return list;}
 static JSONObject train(JSONArray cases)throws Exception{JSONObject out=new JSONObject();for(MethodProgram p:MethodProgram.grammar())out.put(p.id(),new JSONArray(new float[D]));for(int epoch=0;epoch<40;epoch++)for(int i=0;i<cases.length();i++){JSONObject row=cases.getJSONObject(i);float[] x=features(row.getString("instruction"));String best=best(out,x,row.getString("family")),label=row.getString("program");if(!best.equals(label)){JSONArray positive=out.getJSONArray(label),negative=out.getJSONArray(best);for(int d=0;d<D;d++){positive.put(d,positive.getDouble(d)+.2*x[d]);negative.put(d,negative.getDouble(d)-.2*x[d]);}}}for(int i=0;i<cases.length();i++){JSONObject row=cases.getJSONObject(i);if(!best(out,features(row.getString("instruction")),row.getString("family")).equals(row.getString("program")))throw new IllegalArgumentException("El ranking no retuvo todos los ejemplos.");}return out;}
 static String best(JSONObject m,float[] x,String family)throws Exception{String best="";float first=-Float.MAX_VALUE;for(MethodProgram p:MethodProgram.grammar())if(p.family.equals(family)){float score=score(m,p.id(),x);if(score>first){first=score;best=p.id();}}return best;}
 static void validate(JSONObject data)throws Exception{Set<String> ids=new HashSet<>();for(MethodProgram p:MethodProgram.grammar())ids.add(p.id());Iterator<String> it=data.keys();while(it.hasNext()){String id=it.next();if(!ids.contains(id))throw new IllegalArgumentException("Programa desconocido en pesos.");JSONArray row=data.getJSONArray(id);if(row.length()!=D)throw new IllegalArgumentException("Dimensión inválida.");for(int i=0;i<D;i++){double x=row.getDouble(i);if(Double.isNaN(x)||Double.isInfinite(x)||Math.abs(x)>100)throw new IllegalArgumentException("Peso inválido.");}}}
}
